  // New-account questions
  "New to this": ["Baguhan pa lang", "Bag-ohan pa ko", "Soy principiante", "初めて"],
  "Keep it simple and careful, please.": ["Simple at maingat lang, pakiusap.", "Simple ug mainampingon lang, palihug.", "Sencillo y con cuidado, por favor.", "シンプルに、慎重にお願いします。"],
  "I've fixed a few things": ["Nakapag-ayos na ako ng ilang bagay", "Nakaayo na ko og pipila ka butang", "He arreglado algunas cosas", "少し修理したことがある"],
  "I can handle a screwdriver.": ["Kaya kong gumamit ng distornilyador.", "Kaya nako mogamit og distornilyador.", "Sé usar un destornillador.", "ドライバーくらいは使えます。"],
  "I'm comfortable with tools": ["Sanay ako sa mga gamit", "Anad ko sa mga gamit", "Me manejo bien con herramientas", "工具の扱いに慣れている"],
  "Give me the technical details.": ["Ibigay mo sa akin ang mga teknikal na detalye.", "Ihatag nako ang mga teknikal nga detalye.", "Dame los detalles técnicos.", "技術的な詳細を教えてください。"],
  "What should we call you?": ["Ano ang itatawag namin sa iyo?", "Unsa among itawag nimo?", "¿Cómo te llamamos?", "お名前を教えてください"],
  "We'll greet you by your first name.": ["Babatiin ka namin gamit ang pangalan mo.", "Pangumustahon ka namo gamit ang imong ngalan.", "Te saludaremos por tu nombre.", "お名前でごあいさつします。"],
  "Which gadgets do you use?": ["Anong mga gadget ang gamit mo?", "Unsang mga gadget ang imong gigamit?", "¿Qué dispositivos usas?", "どのガジェットを使っていますか？"],
  "Pick all that apply. It helps FixByte AI recognise your devices.": [
    "Piliin lahat ng angkop. Makakatulong ito sa FixByte AI na makilala ang mga device mo.",
    "Pilia ang tanan nga angay. Makatabang kini sa FixByte AI nga mailhan ang imong mga device.",
    "Elige todos los que correspondan. Ayuda a FixByte AI a reconocer tus dispositivos.",
    "当てはまるものをすべて選んでください。FixByte AIがデバイスを認識しやすくなります。",
  ],
  "How handy are you with repairs?": ["Gaano ka kahusay sa pag-aayos?", "Unsa ka kahanas sa pag-ayo?", "¿Qué tan hábil eres con las reparaciones?", "修理はどのくらい得意ですか？"],
  "Your repair guides will match your experience.": ["Iaangkop ang mga repair guide sa karanasan mo.", "Ipahiangay ang mga repair guide sa imong kasinatian.", "Tus guías de reparación se adaptarán a tu experiencia.", "修理ガイドを経験に合わせて調整します。"],
  "Where are you based?": ["Saan ka nakatira?", "Asa ka nagpuyo?", "¿Dónde vives?", "お住まいの地域は？"],
  "Used to find repair shops when your location is off.": ["Ginagamit para maghanap ng repair shop kapag naka-off ang location mo.", "Gigamit aron mangita og repair shop kung naka-off ang imong location.", "Se usa para buscar talleres cuando tu ubicación está desactivada.", "位置情報がオフのときに修理店を探すのに使います。"],
  "Which language should FixByte AI use?": ["Anong wika ang gagamitin ng FixByte AI?", "Unsang pinulongan ang gamiton sa FixByte AI?", "¿Qué idioma debe usar FixByte AI?", "FixByte AIで使う言語は？"],
  "The whole app switches to it, including the AI's answers.": [
    "Lilipat dito ang buong app, pati ang mga sagot ng AI.",
    "Mobalhin niini ang tibuok app, apil ang mga tubag sa AI.",
    "Toda la app cambia a este idioma, incluidas las respuestas de la IA.",
    "AIの回答も含めて、アプリ全体がこの言語になります。",
  ],
  "Previous question": ["Nakaraang tanong", "Miaging pangutana", "Pregunta anterior", "前の質問"],
